description:
(This task was originally a placeholder for collecting the miscellaneous tasks to complete the Bluez DBus peripheral backend support;
identified tasks that are not clearly part of just one of the other tasks under QTBUG-66909). 

Now this task focuses on ensuring the right characteristic/descriptor properties wrt. to encryption, authorization, authentication and extended properties are covered to the extent they can be covered by Qt code. BlueZ DBus API is a high abstraction level API with regards to these, but it needs to be made sure that the expectations towards the application top (Qt) are met. This primarily means proper flag setting during the initial peripheral application registration, and possible DBus replies during application usage.

Now that keyboard navigation feature has been implemented for TableView QML type, it would be good to have a a code snippet which demonstrates its usage.
Currently it does not have a snippet available:
https://doc.qt.io/qt-6/qml-qtquick-tableview.html#keyboard-navigation

As a suggestion, for example, something like the following could be added:

{code:java}
import QtQuick
import QtQuick.Controls
import Qt.labs.qmlmodels 1.0

ApplicationWindow {
    width: 800
    height: 600
    visible: true
    ScrollView {
        anchors.fill: parent
        TableView {
            id: tableView
            clip: true
            interactive: true
            rowSpacing: 1
            columnSpacing: 1
            model: TableModel {
                TableModelColumn { display: "checked" }
                TableModelColumn { display: "amount" }
                TableModelColumn { display: "fruitType" }
                TableModelColumn { display: "fruitName" }
                TableModelColumn { display: "fruitPrice" }

                rows: [
                    {
                        checked: false,
                        amount: 1,
                        fruitType: "Apple",
                        fruitName: "Granny Smith",
                        fruitPrice: 1.50
                    },
                    {
                        checked: true,
                        amount: 4,
                        fruitType: "Orange",
                        fruitName: "Navel",
                        fruitPrice: 2.50
                    },
                    {
                        checked: false,
                        amount: 1,
                        fruitType: "Banana",
                        fruitName: "Cavendish",
                        fruitPrice: 3.50
                    }
                ]
            }
            selectionModel: ItemSelectionModel {}
            delegate: Rectangle {
                implicitWidth: 100
                implicitHeight: 50
                required property bool selected
                required property bool current
                border.width: current ? 2 : 0
                color: selected ? "lightblue" : palette.base
                Text{
                    text: model.display
                    padding: 12
                }
            }
        }
    }
    SelectionRectangle {
        target: tableView
    }
}

{code}

